=== src/cli/commands/check.ts ===
import { BSV_ROOT } from "@bsv/cli/constants.ts";
import { DerivationsTree } from "@bsv/cli/derivations_tree.ts";
import { printCommandHelp } from "@bsv/cli/print_command_help.ts";
import * as Nix from "@bsv/utils/nix/mod.ts";
import { CommandError, run, runCaptureOutput } from "@bsv/utils/run.ts";

export const help = "Check/lint all source code in the repository.";
export const requiresBsvEnv = true;

export default async (argv: ReadonlyArray<string>): Promise<void> => {
  if (argv.length > 0) {
    printCommandHelp({
      name: "check",
      synopsis: help,
      usage: "",
    });
    return;
  }

  Deno.chdir(BSV_ROOT);

  type Check = {
    config: string;
    path: string;
    checkArgs?: Array<string>;
    lintArgs?: Array<string>;
  };

  const checks: Array<Check> = [
    { config: `${BSV_ROOT}/deno.jsonc`, path: `${BSV_ROOT}/src/` },
    {
      config: `${BSV_ROOT}/src/ci/webui/deno.json`,
      path: `${BSV_ROOT}/src/ci/webui/`,
    },
    {
      config: `${BSV_ROOT}/src/report/webui/deno.json`,
      path: `${BSV_ROOT}/src/report/webui/`,
    },
    {
      config: `${BSV_ROOT}/src/utils/webui/deno.json`,
      path: `${BSV_ROOT}/src/utils/webui/`,
    },
  ];

  for (const { config, path, checkArgs, lintArgs } of checks) {
    try {
      await run([
        "deno",
        "check",
        "--doc",
        "--config",
        config,
        path,
        ...(checkArgs ?? []),
      ]);
    } catch (e) {
      if (e instanceof CommandError) {
        Deno.exitCode = e.status.code;
      }
    }

    try {
      await run([
        "deno",
        "lint",
        "--config",
        config,
        path,
        ...(lintArgs ?? []),
      ]);
    } catch (e) {
      if (e instanceof CommandError) {
        Deno.exitCode = e.status.code;
      }
    }
  }

  try {
    const nixFiles =
      (await runCaptureOutput(["git", "--git-dir=/bsv/.git", "ls-files", "-z"]))
        .split("\0").filter((f) => f.endsWith(".nix"));
    await run([
      "nixf-diagnose",
      "--ignore=sema-primop-unknown",
      "--ignore=sema-primop-removed-prefix",
      ...nixFiles,
    ]);
  } catch (e) {
    if (e instanceof CommandError) {
      Deno.exitCode = e.status.code;
    }
  }

  // Evaluate derivations first, since `nix flake check` does not instantiate
  // derivations with `--no-build`.
  const deepEval = async (...args: Array<string>) => {
    console.info("Evaluating...", ...args);

    await run([
      "nix",
      "eval",
      "--apply",
      "x: builtins.deepSeq x null",
      "--show-trace",
      ...args,
    ], { stdout: "null" });
  };

  await deepEval("/bsv#legacyPackages");
  await deepEval("/bsv#checks");
  await deepEval("/bsv#mirror");
  await deepEval("/bsv#reports");

  await run([
    "nix",
    "flake",
    "check",
    "--all-systems",
    "--no-build",
    "--show-trace",
    "/bsv",
  ]);

  const allowedBuilder = new Set([
    "builtin:fetchurl",
    "/bsv/builders/bwrap-builder@v0",
    "/bsv/builders/extract-tarball@v0",
    "/bsv/builders/fetch-git@v0",
    "/bsv/builders/make-content-addressed@v0",
    "/bsv/builders/strict-union@v0",
    "/bsv/builders/to-file@v0",
  ]);

  const drvs = await Nix.derivationShowRecursively(
    "/bsv#checks.x86_64-linux.default",
  );
  for (const [drvName, drv] of Object.entries(drvs)) {
    if (!allowedBuilder.has(drv.builder)) {
      const drvPath = `/nix/store/${drvName}`;
      console.error(
        `%cerror%c: ${drvPath} uses disallowed builder: ${drv.builder}`,
        "color: red; font-weight: bold;",
        "",
      );
      Deno.exitCode = 1;
    }
  }

  const drvTree = JSON.parse(
    await runCaptureOutput([
      "nix",
      "eval",
      "--impure",
      "--json",
      "/bsv#legacyPackages",
      "--apply",
      "(import /bsv/lib/default.nix).extractDerivationsTree",
    ]),
  ) as DerivationsTree;

  const getDrv = (drvTree: DerivationsTree, path: string) => {
    return path.split(".").reduce(
      (acc: DerivationsTree | undefined, fragment: string) => acc?.[fragment],
      drvTree,
    );
  };

  const check = (path: string, value: DerivationsTree) => {
    const checkDrvName = (
      path: string,
      value: DerivationsTree,
      checkAlias: boolean,
    ) => {
      if (value.type !== "derivation") {
        return;
      }

      if (
        value.builder === "/bsv/builders/extract-tarball@v0" &&
        value.system === "bsv-builtin"
      ) {
        return;
      }

      if (
        value.builder === "/bsv/builders/fetch-git@v0" &&
        value.system === "bsv-builtin"
      ) {
        return;
      }

      if (value.builder === "builtin:fetchurl" && value.system === "builtin") {
        return;
      }

      if (value.pname === path) {
        return;
      }

      if (checkAlias) {
        const aliasedDrv = getDrv(drvTree, value.pname);
        if (aliasedDrv) {
          checkDrvName(value.pname, aliasedDrv, false);
          return;
        }
      }

      console.error(
        `%cerror%c: ${path}: mismatching name: ${value.pname}`,
        "color: red; font-weight: bold;",
        "",
      );
      Deno.exitCode = 1;
    };

    checkDrvName(path, value, true);

    for (const [k, v] of Object.entries(value)) {
      if (["builder", "pname", "system", "type"].includes(k)) {
        continue;
      }

      check(path !== "" ? `${path}.${k}` : k, v as DerivationsTree);
    }
  };
  check("", drvTree);
};
=== src/cli/commands/fmt.ts ===
import { BSV_ROOT } from "@bsv/cli/constants.ts";
import { printCommandHelp } from "@bsv/cli/print_command_help.ts";
import { run } from "@bsv/utils/run.ts";

export const help = "Format all source code in the repository.";
export const requiresBsvEnv = true;

export default async (argv: ReadonlyArray<string>): Promise<void> => {
  if (argv.length > 0) {
    printCommandHelp({
      name: "fmt",
      synopsis: help,
      usage: "",
    });
    return;
  }

  await run([
    "bash",
    "-c",
    `nixfmt-tree --working-dir "${BSV_ROOT}" "${BSV_ROOT}"/{*.nix,docs,lib,pkgs,reports,tests}`,
  ], {
    env: {
      "XDG_CACHE_HOME": "/bsv/tmp",
    },
  });
  await run(["deno", "fmt"]);
};
=== src/cli/commands/build.ts ===
import { run } from "@bsv/utils/run.ts";

export const help = "Build derivations.";
export const requiresBsvEnv = true;

export default async (args: ReadonlyArray<string>): Promise<void> => {
  await run([
    "nix",
    "build",
    "--print-build-logs",
    "--no-link",
    "--print-out-paths",
    ...args,
  ]);
};
=== src/cli/commands/init.ts ===
import { ensureDirSync } from "@std/fs";
import { BSV_NIX_DIR, BSV_ROOT, BSV_TMP_DIR } from "@bsv/cli/constants.ts";
import { printCommandHelp } from "@bsv/cli/print_command_help.ts";
import { runCaptureOutput } from "@bsv/utils/run.ts";

export const help = "Initialize BSV.";
export const requiresBsvEnv = false;

export default async (argv: ReadonlyArray<string>): Promise<void> => {
  if (argv.length > 0) {
    printCommandHelp({
      name: "init",
      synopsis: help,
      usage: "",
    });
    return;
  }

  ensureDirSync(BSV_TMP_DIR);
  ensureDirSync(`${BSV_NIX_DIR}/store`);
  ensureDirSync(`${BSV_NIX_DIR}/var/nix`);
  await runCaptureOutput([`${BSV_ROOT}/bin/bash`, "--version"]);
  if (Deno.build.os === "linux") {
    await runCaptureOutput([`${BSV_ROOT}/bin/bwrap`, "--version"]);
  }
  await runCaptureOutput([`${BSV_ROOT}/bin/deno`, "--version"]);
  await runCaptureOutput([`${BSV_ROOT}/bin/nix`, "--version"]);
  await runCaptureOutput([
    `${BSV_ROOT}/bin/bsv`,
    "env",
    "deno",
    "cache",
    `${BSV_ROOT}/src`,
  ]);
};
=== src/cli/commands/env.ts ===
import { BSV_NIX_DIR } from "@bsv/cli/constants.ts";
import * as init from "@bsv/cli/commands/init.ts";
import { execInBsvEnv } from "@bsv/cli/env.ts";
import { printCommandHelp } from "@bsv/cli/print_command_help.ts";
import { parseArgs } from "@bsv/utils/parse_args.ts";

export const help = "Run a command or bash shell under BSV environment.";
export const requiresBsvEnv = false;

export default (argv: ReadonlyArray<string>): void => {
  const args = parseArgs(argv, {
    boolean: ["help", "without-nix"],
    positional: true,
    stopEarly: true,
  });

  if (args.help) {
    printCommandHelp({
      name: "env",
      synopsis: help,
      usage: "[options]... [<command>]",
      options: {
        "--without-nix": "Run with an empty /nix mounted.",
      },
    });
    return;
  }

  init.default([]);

  if (args._.length === 0) {
    args._ = [
      "/bin/bash",
      "--rcfile",
      `/bsv/bsv.bashrc`,
    ];
  }

  execInBsvEnv(!args["without-nix"] ? BSV_NIX_DIR : undefined, args._);
};

