{
  ### Source Derivations

  fetchurl = import <nix/fetchurl.nix>;

  fetchGit = import ./fetch-git.nix;

  fetchTarball = import ./fetch-tarball.nix;

  toFile = import ./to-file.nix;

  ### Helper Derivations

  allDerivations = import ./all-derivations.nix;

  bwrapDerivation = import ./bwrap-derivation.nix;

  extractTarball = import ./extract-tarball.nix;

  localSource = import ./local-source.nix;

  makeContentAddressed = import ./make-content-addressed.nix;

  msys2Derivation = import ./msys2-derivation.nix;

  strictUnion = import ./strict-union.nix;

  tartDerivation = import ./tart-derivation.nix;

  ### Build Scripts

  bashBuilder = import ./bash-builder.nix;

  configureMake = import ./configure-make.nix;

  cmakeBuilder = import ./cmake-builder.nix;

  mesonBuilder = import ./meson-builder.nix;

  ### Flake References

  flakeRefs = {
    nixpkgs = {
      "25.11" = "github:nixos/nixpkgs/871b9fd269ff6246794583ce4ee1031e1da71895";
      "26.05" = "github:nixos/nixpkgs/8c50a710ddca43d7a530fb805ad55bde8d0141c5";
    };
  };

  ### Nix Utilities

  deepRecurseForDerivations =
    x:
    if builtins.isAttrs x && !lib.isDerivation x then
      {
        recurseForDerivations = true;
      }
      // builtins.mapAttrs (_: lib.deepRecurseForDerivations) x
    else
      x;

  extractDerivationsTree = import ./extract-derivations-tree.nix;

  formatCommands =
    cmds:
    builtins.concatStringsSep "\n\n" (
      builtins.map (lib.strings.trim "\n") (builtins.filter (s: s != "") cmds)
    );

  isDerivation = x: builtins.isAttrs x && (x.type or null) == "derivation";

  mapCartesianProduct = import ./map-cartesian-product.nix;

  mapDependentCartesianProduct = import ./map-dependent-cartesian-product.nix;

  normalizeReport = import ./normalize-report.nix;

  parse-triple =
    triple:
    let
      split-triple = builtins.split "-" triple;
    in
    {
      machine = builtins.elemAt split-triple 0;
      vendor = builtins.elemAt split-triple 2;
      os = builtins.elemAt split-triple 4;

      __toString = _: triple;
    };

  strings = import ./strings.nix;

  /**
    Trace and return the argument.
  */
  traceVal = x: builtins.trace x x;

  unimplemented = msg: builtins.abort "unimplemented: ${msg}";
}
