default.nix
{
  bsv,
  build,
  host ? build,
}:
let
  lib = bsv.lib;
in
lib.bwrapDerivation {
  name = "${build.system}.${host.name}.hello-2.12";

  root = [
    build.stdenv-nocc
    build."${host.name}-toolchain"
  ];

  env = {
    src = lib.fetchTarball {
      url = "https://ftp.gnu.org/gnu/hello/hello-2.12.tar.gz";
      hash = "sha256-zwSvhtwIUmjF9EcPuuSbGK+8Iht4CWqrhC2TSna60Ks=";
    };

    inherit (build) PATH;
    inherit (host) CC CFLAGS LDFLAGS;
  };

  builder = lib.configureMake {
    configureFlags = [
      "--build=${build.triple}"
      "--host=${host.triple}"
      "--libdir=${host.libdir}"
      "--prefix=${host.prefix}"
    ];

    postInstall = ''
      rm --recursive --force $out/${host.prefix}/share
    '';
  };

  unsafeDiscardReferences.out = true;

  system = build.system;
}
=== bwrap-derivation.nix ===
/**
  Build a derivation inside BSV's sandbox.
*/
drv:
assert !(drv.__structuredAttrs or false);
assert (drv.__contentAddressed or true);
let
  pname = drv.pname or (builtins.parseDrvName (drv.name or "")).name;
  version = drv.version or (builtins.parseDrvName (drv.name or "")).version;
  name = drv.name or (if version != "" then "${pname}-${version}" else pname);

  realDrv = builtins.derivation {
    inherit name;
    ${if drv ? pname then "pname" else null} = drv.pname;
    ${if drv ? version then "version" else null} = drv.version;

    inherit (drv) root system;
    env = (drv.env or { }) // {
      inherit (drv) builder;
      ${if drv ? args then "args" else null} = drv.args;
    };
    builder = "/bsv/builders/bwrap-builder@v0";
    ${if drv ? capabilities then "capabilities" else null} = drv.capabilities;
    ${if drv ? ccacheDir then "ccacheDir" else null} = drv.ccacheDir;
    ${if drv ? outputs then "outputs" else null} = drv.outputs;
    ${if drv ? outputChecks then "outputChecks" else null} = drv.outputChecks;
    ${if drv ? outputHash then "outputHash" else null} = drv.outputHash;
    ${if drv ? shareNet then "shareNet" else null} = drv.shareNet;
    ${if drv ? requiredSystemFeatures then "requiredSystemFeatures" else null} =
      drv.requiredSystemFeatures;
    ${if drv ? unsafeDiscardReferences then "unsafeDiscardReferences" else null} =
      drv.unsafeDiscardReferences;
    __contentAddressed = true;
    __noChroot = true;
    __structuredAttrs = true;
  };
in
(builtins.removeAttrs realDrv [
  "env"
  "__structuredAttrs"
])
