#!/usr/bin/env -S DENO_DIR=/bsv/tmp/deno /bsv/bin/deno --allow-all --quiet

import { Config, loadConfig } from "@bsv/builders/config.ts";
import {
  getNixStoreReferences,
  NixAttrs as BaseNixAttrs,
} from "@bsv/builders/nixattrs.ts";
import { addOwnerRwXRecursively } from "@bsv/utils/add_owner_rwx_recursively.ts";
import { AtExit } from "@bsv/utils/at_exit.ts";
import { DiagnosticConsole, LogLevel } from "@bsv/utils/console.ts";
import { recursiveStrictUnionCopy } from "@bsv/utils/recursive_strict_union_copy.ts";
import { removeAtomically } from "@bsv/utils/remove_atomically.ts";
import { CommandError, run } from "@bsv/utils/run.ts";

let config: Config = {};

const AllowedCapabilities = [
  "CAP_DAC_OVERRIDE",
  "CAP_SYS_ADMIN",
  "CAP_SYS_CHROOT",
];

type NixAttrs = BaseNixAttrs & {
  capabilities?: Array<string>;
  ccacheDir?: string;
  root: Array<string>;
  shareNet?: boolean;
};

async function main(): Promise<number> {
  const nixAttrsJsonFile = Deno.env.get("NIX_ATTRS_JSON_FILE");
  if (!nixAttrsJsonFile) {
    throw new Error(`error: NIX_ATTRS_JSON_FILE is not set`);
  }

  const nixBuildTop = Deno.env.get("NIX_BUILD_TOP");
  if (!nixBuildTop) {
    throw new Error(`error: NIX_BUILD_TOP is not set`);
  }

  const attrs: NixAttrs = JSON.parse(await Deno.readTextFile(nixAttrsJsonFile));

  const rootfs = `${nixBuildTop}/rootfs`;
  await Deno.mkdir(rootfs, { recursive: true });

  await recursiveStrictUnionCopy(attrs.root, rootfs);
  await addOwnerRwXRecursively(rootfs);

  await Deno.mkdir(`${rootfs}/build`, { recursive: true });

  const nixBuildCores = (() => {
    const env = Deno.env.get("NIX_BUILD_CORES");
    if (env === undefined || env === "0") {
      return navigator.hardwareConcurrency.toString();
    } else {
      return env;
    }
  })();

  const references = await getNixStoreReferences(attrs);
