export type Args = {
  expr?: string;
  file?: string;
  impure?: boolean;
  _: Array<string>;
};

export function parse(args: Args): Array<string> {
  const numExprs = Number(Boolean(args.expr));
  const numFiles = Number(Boolean(args.file));
  const numPositionals = args._.length;

  if (numExprs + numFiles + numPositionals === 0) {
    throw new Error("no installable given");
  }

  if (numExprs + numFiles + numPositionals > 1) {
    throw new Error(
      "--expr, --file and positional installables are mutually exclusive",
    );
  }

  const argv = [];

  if (args.expr) {
    argv.push("--expr", args.expr);
  } else if (args.file) {
    argv.push("--file", args.file);
  } else {
    if (args._.length > 1) {
      throw new Error("Too many positional installables");
    }

    argv.push(...args._);
  }

  if (args.impure) {
    argv.push("--impure");
  }

  return argv;
}

export const optionsHelp = {
  "--expr=<expr>": "Evaluate <expr> as installable.",
  "--file=<file>": "Read <file> as installable.",
  "--impure": "Pass --impure when evaulating Nix expression.",
};

